CREATE TABLE onsite.attendance_facts(id uuid PRIMARY KEY,ticket_id text NOT NULL,event_id uuid NOT NULL REFERENCES onsite.events(id),scope_id uuid NOT NULL REFERENCES onsite.scopes(id),type text NOT NULL CHECK(type IN ('check_in','check_out','void')),actor_id uuid NOT NULL,device_id uuid NOT NULL,occurred_at timestamptz NOT NULL,reason text,compensates_fact_id uuid REFERENCES onsite.attendance_facts(id));
CREATE TABLE onsite.effective_attendance(ticket_id text NOT NULL,event_id uuid NOT NULL REFERENCES onsite.events(id),scope_id uuid NOT NULL REFERENCES onsite.scopes(id),check_in_fact_id uuid NOT NULL REFERENCES onsite.attendance_facts(id),checked_in_at timestamptz NOT NULL,PRIMARY KEY(ticket_id,event_id,scope_id));
CREATE INDEX attendance_history ON onsite.attendance_facts(event_id,scope_id,occurred_at DESC);
